'use strict';
// Resize only unsigned, original AliCDN photos; retain source URLs for zoom/cart.
function supplierImageUrl(source,size=400){
  const original=String(source||'');
  try{const url=new URL(original);if(url.protocol!=='https:'||!/(^|\.)alicdn\.com$/.test(url.hostname)||url.search||url.hash||!/^\/(?:imgextra|bao|tfs)\//.test(url.pathname)||! /\.(?:jpe?g|png)$/i.test(url.pathname)||/_[0-9]+x[0-9]+/.test(url.pathname)||![80,120,400,800].includes(size))return original;
    return original+'_'+size+'x'+size+'q80.jpg_.webp';
  }catch{return original;}
}
function supplierImageAttrs(source,size=400){const resized=supplierImageUrl(source,size);return `src="${esc(resized)}"${resized!==source?` data-image-original="${esc(source)}"`:''} decoding="async"`;}
function productOffersHtml(product,stale){
  const offers=product.offers,fresh=!stale&&offers?.expires*1000>Date.now(),discount=fresh?offers.discount:null;
  const promotions=fresh?(offers.promotions||[]).filter(p=>!p.ends||Date.parse(p.ends)>Date.now()):[];
  return `<section class="product-offers" aria-label="Хямдрал, урамшуулал"><h3>Хямдрал, урамшуулал</h3>${discount?`<p class="supplier-discount"><span>−${discount.percent}%</span> Каталогийн үнэ: <del>${money(discount.was_mnt)}</del> <strong>≈ ${money(discount.current_mnt)}</strong></p>`:''}${promotions.map(p=>`<article><strong>${esc(p.name)}</strong>${p.description?`<p>${esc(p.description)}</p>`:''}${p.price_mnt?`<p>Урамшууллын лавлах үнэ: <strong>≈ ${money(p.price_mnt)}</strong></p>`:''}${p.ends?`<small>Дуусах: ${esc(new Date(p.ends).toLocaleString('mn-MN'))}</small>`:''}</article>`).join('')}${!discount&&!promotions.length?`<p>${!fresh||product.offers_available===false?'Урамшууллын мэдээлэл одоогоор шинэчлэгдээгүй байна.':'Нийлүүлэгчээс баталгаажсан хямдрал, урамшууллын мэдээлэл ирээгүй байна.'}</p>`:'<small>Сонгосон хувилбар, тоо болон урамшууллын нөхцөлөөс хамаарна. Төлөх дүнг захиалга баталгаажуулахад шалгана.</small>'}</section>`;
}
document.addEventListener('error',event=>{const img=event.target;if(img instanceof HTMLImageElement&&img.dataset.imageOriginal){const original=img.dataset.imageOriginal;delete img.dataset.imageOriginal;img.src=original;}},true);
// Optional PHP backend. Static preview retains its browser-only draft behavior.
window.storeServer={ready:false};
let shopCsrf='',qpayEnabled=false;
const REQUESTS_KEY='gostore-server-requests-v1';
function savedRequests(){try{return JSON.parse(localStorage.getItem(REQUESTS_KEY)||'[]').filter(x=>typeof x.id==='string'&&/^[a-f0-9]{64}$/.test(x.token)).slice(0,100);}catch{return [];}}
async function shopApi(action,payload){const response=await fetch('/api/index.php?action='+action,{method:payload?'POST':'GET',credentials:'same-origin',headers:payload?{'Content-Type':'application/json','X-CSRF-Token':shopCsrf}:{},body:payload?JSON.stringify(payload):undefined});const result=await response.json();if(!response.ok){if(response.status===401&&['order-create','customer-orders','customer-me'].includes(action.split('&')[0]))window.customerAccount?.setUser(null);throw Error(result.error||'Сервертэй холбогдсонгүй.');}if(result.csrf)shopCsrf=result.csrf;return result;}
// Only public supplier data is cached; sessions, orders and payments always use shopApi.
window.supplierApi=(()=>{
  const key='gostore-supplier-cache-v6-taoworld',pending=new Map(),maxEntries=40,maxBytes=1500000;
  let entries=[];
  const clone=value=>JSON.parse(JSON.stringify(value));
  const valid=e=>e&&typeof e.key==='string'&&Number.isFinite(e.expires)&&e.expires>Date.now()&&e.expires<=Date.now()+600000&&e.data&&e.data.stale===false;
  try{const saved=JSON.parse(sessionStorage.getItem(key)||'[]');if(Array.isArray(saved))entries=saved.filter(valid).slice(-maxEntries);}catch{/* Storage is optional. */}
  function persist(){
    entries=entries.filter(valid).slice(-maxEntries);
    let json=JSON.stringify(entries);while(json.length*2>maxBytes&&entries.length){entries.shift();json=JSON.stringify(entries);}
    try{sessionStorage.setItem(key,json);}catch{/* Memory cache still works if storage is full or unavailable. */}
  }
  const api=async(action,payload,options={})=>{
    if(!['supplier-search','supplier-product'].includes(action))throw Error('Unsupported public cache action');
    if(action==='supplier-search'&&payload.image){if(!/^[a-f0-9]{32}$/.test(payload.image))throw Error('Зургийн дугаар буруу.');payload={image:payload.image,page:payload.page,...(payload.limit?{limit:payload.limit}:{})};}
    else if(action==='supplier-search')payload={...payload,q:String(payload.q||'__all__').trim().replace(/\s+/g,' ').toLocaleLowerCase()||'__all__'};
    const request=action+':'+JSON.stringify(Object.keys(payload).sort().map(k=>[k,payload[k]]));
    const preview=action==='supplier-search'&&!payload.image&&options.preview===true,refresh=action==='supplier-search'&&!payload.image&&options.refresh===true;
    const workKey=request+(refresh?':refresh':preview?':preview':'');
    const found=!refresh&&entries.find(e=>e.key===request&&valid(e));
    if(found){entries=entries.filter(e=>e!==found);entries.push(found);persist();return clone(found.data);}
    if(!pending.has(workKey)){
      const work=(async()=>{
        const started=Date.now(),url='/api/index.php?'+new URLSearchParams({action,...payload,...(refresh?{refresh:1}:preview?{preview:1}:{}),catalog:'taoworld-catalog1'});
        let response,result;
        for(let attempt=0;attempt<3;attempt++){
          // The first attempt may reuse the request index.html started before scripts loaded.
          const early=attempt===0&&window.earlySupplierProduct?.url===url?window.earlySupplierProduct:null;if(early)window.earlySupplierProduct=null;
          response=await(early?early.response.catch(()=>fetch(url,{credentials:'omit'})):fetch(url,{credentials:'omit'}));result=await response.json();
          if(response.ok||response.status!==503||result.code!=='supplier_busy'||attempt===2)break;
          // Retry only read-only lookups with a typed contention response, never orders/payments.
          await new Promise(resolve=>setTimeout(resolve,Math.min(4,Math.max(1,Number(result.retry_after)||2))*(attempt+1)*1000));
        }
        if(!response.ok){const error=Error(result.error||'Барааны мэдээлэл авч чадсангүй.');error.status=response.status;throw error;}
        // Whitelist fields: never persist an API response's CSRF token or customer data.
        const data={fetched:result.fetched,stale:result.stale,shipping:result.shipping};
        if(action==='supplier-search')Object.assign(data,{products:result.products,page:result.page,more:result.more,total:result.total??null,pages:result.pages??null,brand:result.brand??null,partial:result.partial===true,revalidate:result.revalidate===true});
        else data.product=result.product;
        const ttl=Math.min(action==='supplier-search'?600:300,Number(result.cache_ttl)||0);
        const shaped=action==='supplier-search'?Array.isArray(data.products):data.product?.id===payload.id;
        if(shaped&&!data.partial&&data.stale===false&&ttl>0){entries=entries.filter(e=>e.key!==request);entries.push({key:request,expires:Math.min(started+ttl*1000,Number(result.cache_expires)>0?Number(result.cache_expires)*1000:Infinity),data:clone(data)});persist();}
        return data;
      })();
      pending.set(workKey,work);work.finally(()=>pending.delete(workKey)).catch(()=>{});
    }
    return clone(await pending.get(workKey));
  };
  api.previewProduct=id=>{for(const entry of [...entries].reverse()){if(!valid(entry))continue;const product=entry.data.products?.find(p=>p.id===id)||entry.data.product?.related?.find(p=>p.id===id);if(product)return clone({id:product.id,name:product.name,image:product.image,mnt:product.mnt});}return null;};
  return api;
})();
