/* ==== home-hub.js ==== */
'use strict';
// Marketplace-style first screen: category rows with a hover flyout, popular searches,
// the customer's order shortcuts and, on phones, a two-row grid of category shortcuts.
// Every link is a real URL; plain clicks browse the catalog in place without a reload.
(()=>{
  const hub=document.querySelector('#home-hub');if(!hub)return;
  const byId=id=>categories.find(c=>c.id===id);
  // Each row reads as one phrase ("Эмэгтэй / Эрэгтэй хувцас"), so the labels are shorter than the category names.
  const rows=[[['women','Эмэгтэй'],['men','Эрэгтэй хувцас']],[['women-shoes','Эмэгтэй'],['shoes','Эрэгтэй гутал']],[['bags','Цүнх'],['accessories','Аксессуар']],[['beauty','Гоо сайхан'],['health','Арчилгаа']],[['tech','Электроник'],['appliances','Цахилгаан']],[['home','Гэр ахуй'],['kitchen','Гал тогоо']],[['furniture','Тавилга'],['decor','Чимэглэл'],['lighting','Гэрэл']],[['baby','Нярай'],['kids','Хүүхэд'],['toys','Тоглоом']],[['sports','Спорт'],['outdoor','Аялал, амралт']],[['auto','Авто'],['tools','Багаж, засвар']],[['garden','Цэцэрлэг'],['pets','Амьтны хэрэгсэл']],[['office','Бичиг хэрэг, оффис']]]
    .map(r=>r.map(([id,label])=>byId(id)&&{...byId(id),label}).filter(Boolean)).filter(r=>r.length);
  // Short labels keep the phone grid to one line per tile.
  const channels=[['women','👗','Эмэгтэй'],['men','👔','Эрэгтэй'],['shoes','👟','Гутал'],['bags','👜','Цүнх'],['beauty','💄','Гоо сайхан'],['tech','🎧','Техник'],['home','🏠','Гэр ахуй'],['kids','🧸','Хүүхэд'],['sports','🏃','Спорт']].filter(([id])=>byId(id));
  const hot=[['Пүүз','men sneakers'],['Чихэвч','headphones'],['Үүргэвч','backpack'],['Даашинз','dress'],['Ухаалаг цаг','smart watch'],['Агаар шарагч','air fryer'],['Хадгалах хайрцаг','storage box'],['Арьс арчилгаа','skincare']];
  const categoryHref=id=>'/?category='+encodeURIComponent(id)+'#catalog',queryHref=q=>'/?q='+encodeURIComponent(q)+'#catalog';

  const cats=hub.querySelector('#hub-cats'),flyout=hub.querySelector('#hub-flyout');
  cats.innerHTML=`<h2 class="hub-cats-title">${icon('grid')}Ангилал</h2><ul>${rows.map((r,i)=>`<li data-hub-row="${i}">${r.map(c=>`<a href="${categoryHref(c.id)}" data-hub-category="${esc(c.id)}"${c.label===c.name?'':` aria-label="${esc(c.name)}"`}>${esc(c.label)}</a>`).join('<span aria-hidden="true">/</span>')}</li>`).join('')}</ul>`;
  hub.querySelector('#hub-channels').innerHTML=channels.map(([id,emoji,label])=>`<a href="${categoryHref(id)}" data-hub-category="${esc(id)}"><span aria-hidden="true">${emoji}</span>${esc(label)}</a>`).join('')+`<button type="button" data-hub-all-categories><span aria-hidden="true">${icon('grid')}</span>Бүгд</button>`;
  hub.querySelector('#hub-hot').innerHTML=`<span>Түгээмэл хайлт</span>`+hot.map(([label,q])=>`<a href="${queryHref(q)}" data-hub-query="${esc(q)}">${esc(label)}</a>`).join('');

  // Flyout: the row under the pointer (or keyboard focus) lists its subcategories.
  let open=null,closeTimer=0;
  function show(index){
    clearTimeout(closeTimer);if(open===index)return;open=index;
    cats.querySelectorAll('[data-hub-row]').forEach(li=>li.classList.toggle('active',li.dataset.hubRow===String(index)));
    flyout.innerHTML=rows[index].map(c=>`<section><h3><a href="${categoryHref(c.id)}" data-hub-category="${esc(c.id)}">${esc(c.name)} ${icon('arrow')}</a></h3><div>${c.children.map(x=>`<a href="${queryHref(x.query)}" data-hub-query="${esc(x.query)}">${esc(x.name)}</a>`).join('')}</div></section>`).join('');
    flyout.hidden=false;
  }
  function hide(){clearTimeout(closeTimer);open=null;flyout.hidden=true;cats.querySelectorAll('.active').forEach(li=>li.classList.remove('active'));}
  const hideSoon=()=>{clearTimeout(closeTimer);closeTimer=setTimeout(hide,180);};
  const hoverable=()=>matchMedia('(hover: hover) and (min-width: 761px)').matches;
  cats.addEventListener('mouseover',e=>{const li=e.target.closest('[data-hub-row]');if(li&&hoverable())show(Number(li.dataset.hubRow));});
  cats.addEventListener('focusin',e=>{const li=e.target.closest('[data-hub-row]');if(li&&getComputedStyle(cats).display!=='none')show(Number(li.dataset.hubRow));});
  for(const el of [cats,flyout]){el.addEventListener('mouseleave',hideSoon);el.addEventListener('mouseenter',()=>clearTimeout(closeTimer));}
  hub.addEventListener('focusout',e=>{if(!cats.contains(e.relatedTarget)&&!flyout.contains(e.relatedTarget))hide();});
  hub.addEventListener('keydown',e=>{if(e.key==='Escape'&&!flyout.hidden){const row=cats.querySelector('.active a');hide();row?.focus();}});

  hub.addEventListener('click',e=>{
    if(e.target.closest('[data-hub-all-categories]')){document.querySelector('#category-trigger')?.click();return;}
    const link=e.target.closest('[data-hub-category],[data-hub-query]');
    if(!link||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||typeof window.supplierBrowse!=='function')return;
    e.preventDefault();hide();
    const c=link.dataset.hubCategory&&byId(link.dataset.hubCategory);
    if(c)window.supplierBrowse(c.query,false,c.id);else window.supplierBrowse(link.dataset.hubQuery);
    scrollCatalog();
  });
  hub.querySelector('[data-hub-register]')?.addEventListener('click',()=>window.customerAccount?customerAccount.open('register'):runAction('account'));

  // Cart and saved counts follow the header badges.
  const counts=()=>{for(const [key,source] of [['cart','#cart-count'],['favorites','#favorite-count']]){const from=document.querySelector(source),to=hub.querySelector(`[data-hub-count="${key}"]`);if(from&&to){to.textContent=from.hidden?'':from.textContent;}}};
  for(const source of ['#cart-count','#favorite-count']){const el=document.querySelector(source);if(el)new MutationObserver(counts).observe(el,{childList:true,attributes:true,attributeFilter:['hidden']});}
  counts();
})();
;
/* ==== barcode.js ==== */
'use strict';
// Code 39: locally rendered, readable by standard USB/Bluetooth barcode scanners.
function code39(value){
  const alphabet='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%*';
  const patterns=['nnnwwnwnn','wnnwnnnnw','nnwwnnnnw','wnwwnnnnn','nnnwwnnnw','wnnwwnnnn','nnwwwnnnn','nnnwnnwnw','wnnwnnwnn','nnwwnnwnn','wnnnnwnnw','nnwnnwnnw','wnwnnwnnn','nnnnwwnnw','wnnnwwnnn','nnwnwwnnn','nnnnnwwnw','wnnnnwwnn','nnwnnwwnn','nnnnwwwnn','wnnnnnnww','nnwnnnnww','wnwnnnnwn','nnnnwnnww','wnnnwnnwn','nnwnwnnwn','nnnnnnwww','wnnnnnwwn','nnwnnnwwn','nnnnwnwwn','wwnnnnnnw','nwwnnnnnw','wwwnnnnnn','nwnnwnnnw','wwnnwnnnn','nwwnwnnnn','nwnnnnwnw','wwnnnnwnn','nwwnnnwnn','nwnwnwnnn','nwnwnnnwn','nwnnnwnwn','nnnwnwnwn','nwnnwnwnn'];
  if(!/^[A-Z0-9-]{1,50}$/.test(value))return '';
  let x=12,bars='';for(const c of '*'+value+'*'){const p=patterns[alphabet.indexOf(c)];for(let i=0;i<9;i++){const w=p[i]==='w'?3:1;if(i%2===0)bars+=`<rect x="${x}" y="0" width="${w}" height="48"/>`;x+=w;}x++;}
  return `<svg class="code-bar" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${x+12} 64" role="img" aria-label="${value}"><rect width="100%" height="100%" fill="white"/><g fill="black">${bars}</g><text x="${(x+12)/2}" y="61" text-anchor="middle" fill="black" font-size="9" font-family="monospace">${value}</text></svg>`;
}
;
/* ==== cargo.js ==== */
'use strict';
function cargoDate(value,dateOnly=false){
  const when=new Date(value);if(!Number.isFinite(when.getTime()))return '—';
  const parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Ulaanbaatar',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(when).map(p=>[p.type,p.value]));
  return parts.year+'.'+parts.month+'.'+parts.day+(dateOnly?'':' · '+parts.hour+':'+parts.minute);
}
function cargoPhotosHtml(photos=[]){
  if(!photos.length)return '';
  const warehouses=Object.fromEntries(photos.map(p=>[p.location,p.warehouse_name||({erenhot:'Эрээн агуулах',ulaanbaatar:'Улаанбаатар агуулах'}[p.location])||'Агуулах']));
  return '<section class="cargo-photo-section"><h3>Агуулахад бүртгэсэн зураг</h3><p>Зураг дээр дарж томруулж харна уу.</p>'+Object.entries(warehouses).map(([location,label])=>{
    const rows=photos.filter(p=>p.location===location);if(!rows.length)return '';
    return `<section data-photo-warehouse="${esc(location)}"><h4>${esc(label)}</h4><div class="cargo-photos">${rows.map(p=>`<figure><button type="button" data-cargo-photo-toggle aria-expanded="false" aria-label="${esc(label)}ын зургийг томруулах"><img data-cargo-photo="${esc(p.id)}" alt="${esc(label)}ад бүртгэсэн бараа" loading="lazy"></button><figcaption><time datetime="${esc(p.at)}">${esc(cargoDate(p.at))}</time></figcaption></figure>`).join('')}</div></section>`;
  }).join('')+'</section>';
}
function cargoPickupWarehouse(o){const w=o.pickup_warehouse;if(!w?.address)return '';return `<section class="info-box"><h3>${esc(w.name)}</h3><p style="white-space:pre-line">${esc(w.address)}</p><p>Утас: ${esc(w.phone)}${w.contact_phone?' · '+esc(w.contact_phone):''}</p>${w.hours?`<p>Ажиллах цаг: ${esc(w.hours)}</p>`:''}</section>`;}
let cargoList=[],cargoFilter='all',cargoQuery='',cargoRequest=0,cargoUserSwitches=0,cargoNoticeThrough=0;
const cargoNext=o=>o.cancel_reason==='payment_timeout'?'Төлбөрийн хугацаа дууссан тул автоматаар цуцлагдсан. Сагсаа дахин захиална уу.':o.payment_due&&o.status==='quoted'&&!o.paid?'Төлөх хугацаа: '+cargoDate(o.payment_due)+' хүртэл. Төлбөр орсны дараа нийлүүлэгчээс захиална.':o.status==='cancelled'?'Захиалга цуцлагдсан. Асуух зүйл байвал GOStore-той холбогдоно уу.':o.cargo?.issue_count?'Агуулах зөрчлийг шалгаж байна.':o.cargo?.billing?.due&&o.cargo?.billing?.finalized?'Үлдэгдэл төлбөрөө төлөөд авах кодоо харна уу.':o.status==='ready_pickup'?'Авах кодоо агуулахын ажилтанд үзүүлнэ үү.':o.status==='out_for_delivery'?'Бараагаа авах үедээ хүргэгчид авах кодоо хэлнэ үү.':o.status==='erenhot_ready'?'Барааг багцалж дууссан. Агуулахаас илгээхийг хүлээж байна.':o.status==='erenhot_dispatched'?(o.warehouse_names?.erenhot||'Эрээн агуулах')+'-аас гарсан. Замын-Үүдээр дамжин '+(o.warehouse_names?.ulaanbaatar||'Улаанбаатар агуулах')+' руу хүргэгдэнэ.':o.status==='quoted'?'Үнийн саналаа шалгаж төлбөрөө төлнө үү.':o.status==='completed'?'Барааг хүлээлгэн өгсөн.':'Дараагийн төлөв шинэчлэгдэхэд сайтын мэдэгдэлд харагдана.';
const cargoGroup=o=>o.status==='cancelled'?'cancelled':o.status==='quoted'&&!o.paid?'payment':o.status==='completed'?'done':o.cargo?.billing?.finalized&&o.cargo.billing.due>0?'payment':['ready_pickup','ready_delivery','out_for_delivery'].includes(o.status)?'ready':'transit';
function cargoProgress(o){
  const stage={new:0,reviewing:0,quoted:0,confirmed:0,shipping:0,erenhot:1,erenhot_ready:1,erenhot_dispatched:2,zamyn_uud:2,ulaanbaatar_unsorted:3,ulaanbaatar:3,ready_pickup:3,ready_delivery:3,out_for_delivery:3,completed:4}[o.status];
  if(stage===undefined)return '';
  return '<ol class="cargo-progress" aria-label="Ачааны явц">'+['Захиалсан',o.warehouse_names?.erenhot||'Эрээнд ирсэн','Замд',o.warehouse_names?.ulaanbaatar||'УБ-д ирсэн','Хүлээн авсан'].map((label,i)=>`<li class="${i<stage?'done':i===stage?'current':'pending'}" ${i===stage?'aria-current="step"':''} title="${esc(label)}"><span aria-hidden="true">${i<stage?'✓':i+1}</span>${esc(label.replace(/^Улаанбаатар(?= |$)/,'УБ'))}</li>`).join('')+'</ol>';
}
function cargoCards(){
  const rows=cargoList.filter(o=>(cargoFilter==='all'||cargoGroup(o)===cargoFilter)&&(!cargoQuery||(o.id+' '+o.title).toLowerCase().includes(cargoQuery.toLowerCase())));
  return rows.length?rows.map(o=>`<article class="cargo-card"><div><span class="cargo-code">${esc(o.id)}</span><span class="cargo-status">${esc(orderStatusLabel(o))}</span></div><h3>${esc(o.title)}</h3><p>${esc(cargoNext(o))}</p><div class="cargo-card-footer"><small>${cargoDate(o.created,true)}</small><strong>${o.cargo?.billing?.finalized?'Үлдэгдэл '+money(o.cargo.billing.due):'Эцсийн тооцоо хүлээгдэж байна'}</strong></div><button class="button outline" data-server-order="${esc(o.id)}">Дэлгэрэнгүй →</button></article>`).join(''):`<div class="empty-state">${icon('box')}<h3>${cargoQuery||cargoFilter!=='all'?'Тохирох ачаа алга':'Энд таны захиалга харагдана'}</h3><p>${cargoQuery||cargoFilter!=='all'?'Код, барааны нэр эсвэл төлөвийн шүүлтүүрээ шалгаарай.':'Бараагаа сонгон захиалсны дараа явцыг эндээс хянана.'}</p>${cargoQuery||cargoFilter!=='all'?'<button class="button outline" data-cargo-reset>Шүүлтүүр цэвэрлэх</button>':'<button class="button blue" data-action="browse">Бараа үзэх</button>'}</div>`;
}
storeServer.orders=async(offset=0)=>{
  let request=++cargoRequest;const switches=cargoUserSwitches;
  try{
    await customerAccount.refresh();
    // refresh() can sign the customer in right after page load, and setUser() then bumps the
    // counter. Bumps from that sign-in alone must not cancel this list; a newer request still does.
    if(cargoRequest-request===cargoUserSwitches-switches)request=cargoRequest;else return;
    const user=customerAccount.user;if(!user)return accountForm();
    const r=user?await shopApi('customer-orders&offset='+offset):{orders:[],more:false};
    const own=new Set(r.orders.map(o=>o.id)),guest=savedRequests().filter(g=>!own.has(g.id));
    const fetched=offset===0?await Promise.allSettled(guest.map(g=>shopApi('order-get',g))):[];
    if(request!==cargoRequest)return;cargoList=[...r.orders,...fetched.filter(x=>x.status==='fulfilled').map(x=>x.value.order)];
    openModal('Миний ачаа',`<p class="modal-intro">Захиалгын кодоороо явц, төлбөр, авах мэдээллээ нэг дороос хараарай.</p>${!user?'<button class="button blue" data-action="account">Нэвтрэх / Бүртгүүлэх</button><p>Энэ хөтөчид хадгалсан захиалгууд харагдана.</p>':''}<div class="cargo-toolbar"><label class="field">Код / барааны нэр<input id="cargo-search" value="${esc(cargoQuery)}" placeholder="GS-A1B2C3"></label><label class="field">Төлөв<select id="cargo-filter">${Object.entries({all:'Бүгд',transit:'Замд / Бэлтгэж байна',payment:'Төлбөр хүлээж байна',ready:'Авах / Хүргүүлэх',done:'Хүлээн авсан',cancelled:'Цуцлагдсан'}).map(([k,v])=>`<option value="${k}" ${k===cargoFilter?'selected':''}>${v}</option>`).join('')}</select></label></div><p class="account-hint">Энэ хуудсанд ${cargoList.length} захиалга · Код эсвэл нэрээр хайна.</p><div id="cargo-cards">${cargoCards()}</div>${user&&(offset>0||r.more)?`<div class="form-actions">${offset>0?`<button class="button outline" data-orders-offset="${Math.max(0,offset-20)}">Өмнөх</button>`:''}${r.more?`<button class="button outline" data-orders-offset="${offset+20}">Дараах</button>`:''}</div>`:''}${user&&guest.length?`<details><summary>Энэ хөтчийн хүсэлтийг бүртгэлдээ холбох</summary>${guest.map(g=>`<p>${esc(g.id)} <button class="text-button" data-claim-order="${esc(g.id)}">Холбох</button></p>`).join('')}</details>`:''}`);
    refreshCargoNotifications().catch(()=>{});
  }catch(e){toast(e.message);}
};
function cargoPaymentHtml(invoice){return invoice?.state==='ready'?`<div class="cargo-payment"><img alt="QPay төлбөрийн QR" src="data:image/png;base64,${esc((invoice.qr_image||'').replace(/[^a-zA-Z0-9+/=]/g,''))}"><div class="bank-links" aria-label="Банкны аппаар төлөх">${(invoice.urls||[]).filter(x=>bankUrl(x.link)).map(x=>`<a class="button outline" href="${esc(bankUrl(x.link))}" rel="noopener noreferrer">${String(x.logo||'').startsWith('https://')?`<img src="${esc(x.logo)}" alt="" width="24" height="24" loading="lazy" referrerpolicy="no-referrer">`:''}<span>${esc(x.description||x.name)}</span></a>`).join('')}</div></div>`:invoice?'<p class="form-error">Нэхэмжлэлийг админ шалгаж байна. Давтан төлбөр бүү үүсгээрэй.</p>':'';}
viewServerOrder=async(id,requestInvoice=false,action=null)=>{
  const request=++cargoRequest,r=savedRequests().find(x=>x.id===id)||{id,token:''};
  try{
    if(!await customerAccount.refresh())return accountForm();
    const {order:o}=await shopApi(action||(requestInvoice?'invoice':'order-get'),r);if(request!==cargoRequest)return;
    const c=o.cargo||{},bill=c.billing||{finalized:false,total:o.amount,paid:o.paid?o.amount:0,due:o.paid?0:o.amount,breakdown:o.quote?.breakdown||{}},m=c.measurement;
    const labels={goods_mnt:'Бараа',domestic_mnt:'Хятад доторх хүргэлт',service_mnt:'Үйлчилгээ',cargo_mnt:'Карго',delivery_mnt:'УБ хүргэлт'};
    const history=[{status:'new',at:o.created},...(o.history||[])];
    openModal('Ачааны дэлгэрэнгүй',`<div class="cargo-detail"><div class="cargo-detail-code"><strong>${esc(o.id)}</strong><button class="text-button" data-copy-cargo="${esc(o.id)}">Код хуулах</button></div><span class="cargo-status">${esc(orderStatusLabel(o))}</span><h3>${esc(o.title)}</h3><p class="cargo-next-step">${esc(cargoNext(o))}</p>${cargoProgress(o)}${o.supplier?.image?`<img class="cargo-product" src="${esc(o.supplier.image)}" alt="${esc(o.title)}" referrerpolicy="no-referrer">`:''}${o.type==='checkout'&&o.items?.length?`<ul class="cargo-items">${o.items.map(i=>`<li>${esc(i.name)} · ${esc(i.variant)} × ${i.qty}</li>`).join('')}</ul>`:`<p>${esc(o.supplier?.variant||o.variant||'')} ${o.supplier?.qty?'× '+o.supplier.qty:''}</p>`}${c.issue_count?'<div class="info-box">Агуулахад зөрчил бүртгэгдсэн. Шалгалт дуусмагц явц шинэчлэгдэнэ.</div>':''}${cargoPickupWarehouse(o)}${!o.fulfillment&&o.fulfillment_request?.method==='delivery'?`<div class="info-box"><strong>Хүргэлтээр авна</strong><p>${esc(o.delivery_address||'')}</p><p>УБ хүргэлтийн төлбөрийг эцсийн тооцоонд нэмнэ.</p></div>`:''}${c.pickup_code?`<section class="pickup-pass"><h3>${o.status==='ready_pickup'?'Агуулахаас авах код':'Хүргэлт хүлээн авах код'}</h3><strong>${esc(c.pickup_code)}</strong>${code39(c.pickup_code)}<p>Бараагаа авах үедээ ажилтанд үзүүлнэ үү. Нэг удаа ашиглана.</p></section>`:''}<details ${["ready_pickup","out_for_delivery","completed"].includes(o.status)?"":"open"}><summary>Явцын түүх</summary><ol class="cargo-timeline">${history.map(h=>`<li><strong>${esc(orderStatusLabel(o,h.status))}</strong><small>${cargoDate(h.at)}</small></li>`).join('')}</ol></details>${cargoPhotosHtml(c.photos)}${o.type==='checkout'&&o.quote?`<details class="order-calculation" ${bill.finalized?'':'open'}><summary>${esc(commerceUI.calculationTitle)}</summary>${commerceUI.calculationHtml(o.quote,o.items||[],commerceUI.calculationTitle,'Захиалгын эхний төлбөр')}</details>`:''}<section class="cargo-bill">${bill.finalized&&o.quote?`<p>Урьдчилсан тооцоо: ${money(o.quote.total)} · Зөрүү: ${money(bill.total-o.quote.total)}</p>`:''}<h3>${bill.finalized?'Эцсийн тооцоо':o.type==='checkout'?'Урьдчилан төлөх дүн':'Урьдчилсан үнийн санал'}</h3>${Object.entries(labels).filter(([k])=>k in bill.breakdown).map(([k,v])=>`<div><span>${v}</span><strong>${k==='cargo_mnt'&&!bill.finalized&&o.quote?.cargo_later?'Улаанбаатарт ирэхэд бодит жингээр':k==='domestic_mnt'&&!bill.finalized&&o.quote?.domestic_later?'Улаанбаатарт ирэхэд бодит дүнгээр':money(bill.breakdown[k])}</strong></div>`).join('')}<div><span>Нийт</span><strong>${money(bill.total)}</strong></div><div><span>Төлсөн</span><strong>${money(bill.paid)}</strong></div><div class="cargo-total"><span>Үлдэгдэл</span><strong>${money(bill.due)}</strong></div>${bill.refund_due?`<p class="form-error">Илүү төлөлт ${money(bill.refund_due)}. Админ буцаалтыг тулгаж шалгана.</p>`:''}</section>${m?`<section><h3>Агуулахын хэмжилт</h3><p>${m.weight_kg} кг · ${m.length_cm} × ${m.width_cm} × ${m.height_cm} см · ${m.volume_m3} м³ · ${m.pieces} ширхэг</p></section>`:''}${o.fulfillment?`<p>Хүлээн авах: ${o.fulfillment.method==='pickup'?'Агуулахаас авах':'Хүргэлтээр авах'}</p>`:''}${!o.paid?cargoPaymentHtml(o.invoice):''}${bill.due>0?cargoPaymentHtml(c.freight_invoice):''}<div class="form-actions"><button class="button outline" data-server-order="${esc(o.id)}">Төлөв шинэчлэх</button>${qpayEnabled&&!o.demo&&o.status==='quoted'&&!o.paid?`<button class="button blue" data-invoice="${esc(o.id)}">Эхний төлбөр · QPay</button>`:''}${qpayEnabled&&!o.demo&&bill.finalized&&bill.due>0?`<button class="button blue" data-freight-invoice="${esc(o.id)}">Үлдэгдэл төлөх · QPay</button>`:''}${qpayEnabled&&(o.invoice||c.freight_invoice)?`<button class="button outline" data-payment-check="${esc(o.id)}">Төлбөр шалгах</button>`:''}</div><button class="text-button" data-action="orders">← Миний ачаа</button></div>`);
    document.querySelectorAll('[data-cargo-photo]').forEach(async img=>{try{const res=await fetch('/api/index.php?action=order-photo',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':shopCsrf},body:JSON.stringify({...r,photo:img.dataset.cargoPhoto})});if(!res.ok)throw Error();const blob=await res.blob();if(!img.isConnected)return;const url=URL.createObjectURL(blob);img.onload=()=>URL.revokeObjectURL(url);img.onerror=()=>URL.revokeObjectURL(url);img.src=url;}catch{img.alt='Зураг ачаалсангүй. Төлөв шинэчилж дахин оролдоно уу.';}});
    watchCargoPayment(r,o,request);
  }catch(e){toast(e.message);}
};
// While an unpaid QPay invoice is open, follow the server-side callback so the customer
// does not need to press "Төлбөр шалгах" after returning from the bank app.
let cargoPaymentWatch=null;
const cargoDue=o=>!o.paid&&o.invoice?.state==='ready'?'initial':o.cargo?.freight_invoice&&o.cargo?.billing?.due>0?'freight':null;
function stopCargoPaymentWatch(){cargoPaymentWatch?.();cargoPaymentWatch=null;}
function watchCargoPayment(r,o,request){
  stopCargoPaymentWatch();const kind=cargoDue(o);if(!kind)return;
  const modal=document.querySelector('#modal'),started=Date.now();let ticks=0,busy=false;
  const check=async full=>{
    if(request!==cargoRequest||!modal.open||Date.now()-started>15*60*1000){stopCargoPaymentWatch();return;}
    if(busy)return;busy=true;
    // order-get reads the stored order; payment-check also asks QPay in case its callback was missed.
    try{const {order:next}=await shopApi(full?'payment-check':'order-get',r);if(request===cargoRequest&&modal.open&&!cargoDue(next)){stopCargoPaymentWatch();cargoPaymentSuccess(next,kind);}}catch{}finally{busy=false;}
  };
  const timer=setInterval(()=>check(++ticks%8===0),4000);
  const returned=()=>{if(document.visibilityState==='visible')check(true);};
  document.addEventListener('visibilitychange',returned);modal.addEventListener('close',stopCargoPaymentWatch,{once:true});
  cargoPaymentWatch=()=>{clearInterval(timer);document.removeEventListener('visibilitychange',returned);modal.removeEventListener('close',stopCargoPaymentWatch);};
}
function cargoPaymentSuccess(o,kind){
  const paid=o.cargo?.billing?.paid??o.amount;
  if(kind==='initial')window.gtag?.('event','purchase',{transaction_id:o.id,value:o.amount,currency:'MNT'});
  const next=kind==='freight'?['Улаанбаатар агуулах бараагаа хүлээлгэн өгөхөд бэлдэнэ.','Авах код «Миний захиалга» хэсэгт гарна.']:['GOStore бараагаа Taobao-оос худалдан авна.','Эрээн агуулахад ирэхэд зурагтай мэдэгдэл ирнэ.','Улаанбаатарт ирэхэд каргог бодит жингээр тооцож, авах код гарна.'];
  openModal('Төлбөр амжилттай',`<div class="payment-success" role="status"><span class="payment-success-icon" aria-hidden="true">✓</span><h3>${kind==='freight'?'Үлдэгдэл төлбөр баталгаажлаа':'Таны захиалга баталгаажлаа'}</h3><p>Захиалгын код <strong>${esc(o.id)}</strong> · Төлсөн ${money(paid)}</p><ol class="payment-next">${next.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><div class="form-actions"><button class="button blue" data-server-order="${esc(o.id)}">Захиалгын явц харах</button><button class="button outline" data-payment-done>Дэлгүүр үргэлжлүүлэх</button></div></div>`);
}
document.addEventListener('click',e=>{if(e.target.closest('[data-payment-done]'))document.querySelector('#close-modal').click();});
async function refreshCargoNotifications(){if(!window.customerAccount?.user){document.querySelectorAll('[data-notification-count]').forEach(n=>n.textContent='');return null;}const userId=customerAccount.user.id,d=await shopApi('customer-notifications');if(customerAccount.user?.id!==userId)return null;document.querySelectorAll('[data-notification-count]').forEach(n=>n.textContent=d.unread?String(d.unread):'');return d;}
async function showCargoNotifications(){if(!window.customerAccount?.user){await customerAccount.open();return;}const d=await refreshCargoNotifications();if(!d)return;cargoNoticeThrough=d.notifications[0]?.id||0;openModal('Мэдэгдэл',`<p class="modal-intro">Захиалгын явц болон төлбөрийн шинэчлэлтүүд.</p>${d.notifications.length?`<button class="button outline" data-read-notifications>Бүгдийг уншсан болгох</button>${d.notifications.map(n=>`<article class="cargo-notice ${n.read_at?'':'unread'}"><strong>${n.kind==='status'?esc(orderLabels[n.message]||n.message):esc(n.message)}</strong><p>${esc(n.order_id)} · ${cargoDate(n.created)}</p><button class="text-button" data-server-order="${esc(n.order_id)}">Ачаа харах →</button></article>`).join('')}`:'<div class="empty-state">Шинэ мэдэгдэл алга.</div>'}`);}
document.addEventListener('input',e=>{if(e.target.id==='cargo-search'){cargoQuery=e.target.value;$('#cargo-cards').innerHTML=cargoCards();}});
document.addEventListener('change',e=>{if(e.target.id==='cargo-filter'){cargoFilter=e.target.value;$('#cargo-cards').innerHTML=cargoCards();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-cargo-reset')){cargoFilter='all';cargoQuery='';$('#cargo-search').value='';$('#cargo-filter').value='all';$('#cargo-cards').innerHTML=cargoCards();$('#cargo-search').focus();}if(b.dataset.copyCargo){try{await navigator.clipboard.writeText(b.dataset.copyCargo);toast('Захиалгын кодыг хууллаа');}catch{toast('Кодыг сонгож гараар хуулна уу: '+b.dataset.copyCargo);}}if(b.hasAttribute('data-notifications'))await showCargoNotifications();if(b.hasAttribute('data-read-notifications')){await shopApi('customer-notifications-read',{through_id:Number(cargoNoticeThrough)});await showCargoNotifications();}if(b.dataset.freightInvoice||b.dataset.paymentCheck){b.disabled=true;await viewServerOrder(b.dataset.freightInvoice||b.dataset.paymentCheck,false,b.dataset.freightInvoice?'freight-invoice':'payment-check');}}catch(err){toast(err.message);}finally{b.disabled=false;}});
setInterval(()=>{if(!document.hidden&&window.customerAccount?.user)refreshCargoNotifications().catch(()=>{});},60000);
